import { z } from "zod";

/**
 * cube-viz spec contract (v1) — the stable, library-agnostic source of truth.
 * zod schemas are authoritative; all TS types are `z.infer`-ed from them, so the
 * runtime guard and the compile-time type can never drift.
 *
 * See docs/01-spec-schema.md for the full rationale.
 */

export const SCHEMA_VERSION = 5 as const;

/* ────────────────────────── variable reference token ────────────────────── */

/** Anywhere a literal value may appear, the spec may instead carry `{ var: "name" }`. */
export const VarRefSchema = z.object({ var: z.string().min(1) }).strict();
export type VarRef = z.infer<typeof VarRefSchema>;

export function isVarRef(v: unknown): v is VarRef {
  return typeof v === "object" && v !== null && "var" in v && typeof (v as VarRef).var === "string";
}

/** `T | VarRef` — a value position that may be bound to a variable. */
const orVar = <T extends z.ZodTypeAny>(s: T) => z.union([s, VarRefSchema]);

/* ────────────────────────────── primitives ──────────────────────────────── */

export const ScalarSchema = z.union([z.string(), z.number(), z.boolean()]);
export type Scalar = z.infer<typeof ScalarSchema>;

export const GranularitySchema = z.enum([
  "second",
  "minute",
  "hour",
  "day",
  "week",
  "month",
  "quarter",
  "year",
]);
export type Granularity = z.infer<typeof GranularitySchema>;

/**
 * "auto" is a SPEC-level granularity choice, not a Cube one: it means "pick a bucket
 * that fits the date range at query time" (2 days → hour, a quarter → day, two years
 * → month…). The variable resolver replaces it with a concrete {@link Granularity}
 * before the query is POSTed, so Cube never sees the token — and the chart keeps a
 * sensible bucket when the user (or a dashboard variable) later changes the range.
 */
export const AUTO_GRANULARITY = "auto" as const;
export const GranularityChoiceSchema = z.union([GranularitySchema, z.literal(AUTO_GRANULARITY)]);
/** What a spec may STORE for a time bucket: a concrete granularity, or "auto". */
export type GranularityChoice = z.infer<typeof GranularityChoiceSchema>;

/** Absolute `[from, to]` pair OR a relative string like "last 30 days" / "This month". */
export const DateRangeSchema = z.union([z.tuple([z.string(), z.string()]), z.string()]);
export type DateRange = z.infer<typeof DateRangeSchema>;

export const VariableValueSchema = z.union([
  z.string(),
  z.number(),
  z.boolean(),
  z.tuple([z.string(), z.string()]), // absolute date range
  z.array(z.string()),
  z.array(z.number()),
]);
export type VariableValue = z.infer<typeof VariableValueSchema>;

/** Fully-qualified, dot-namespaced Cube member, e.g. "device_trips.total_distance". */
export const MemberSchema = z.string().min(1);
export type Member = z.infer<typeof MemberSchema>;

/* ──────────────────────────────── query ─────────────────────────────────── */

export const FilterOperatorSchema = z.enum([
  "equals",
  "notEquals",
  "gt",
  "gte",
  "lt",
  "lte",
  "contains",
  "notContains",
  "startsWith",
  "endsWith",
  "set",
  "notSet",
  "inDateRange",
  "notInDateRange",
  "beforeDate",
  "beforeOrOnDate",
  "afterDate",
  "afterOrOnDate",
  "measureFilter",
]);
export type FilterOperator = z.infer<typeof FilterOperatorSchema>;

export const LeafFilterSchema = z
  .object({
    member: MemberSchema,
    operator: FilterOperatorSchema,
    values: z.array(z.union([ScalarSchema, VarRefSchema])).optional(),
  })
  .strict();
export type LeafFilter = z.infer<typeof LeafFilterSchema>;

export type QueryFilter = LeafFilter | { and: QueryFilter[] } | { or: QueryFilter[] };
export const QueryFilterSchema: z.ZodType<QueryFilter> = z.lazy(() =>
  z.union([
    LeafFilterSchema,
    z.object({ and: z.array(QueryFilterSchema) }).strict(),
    z.object({ or: z.array(QueryFilterSchema) }).strict(),
  ]),
);

export const TimeDimensionSchema = z
  .object({
    dimension: MemberSchema,
    granularity: orVar(GranularityChoiceSchema).optional(),
    dateRange: orVar(DateRangeSchema).optional(),
    compareDateRange: z.array(DateRangeSchema).optional(),
  })
  .strict();
export type TimeDimension = z.infer<typeof TimeDimensionSchema>;

export const OrderDirSchema = z.enum(["asc", "desc"]);
export const OrderSpecSchema = z.union([
  z.record(MemberSchema, OrderDirSchema),
  z.array(z.tuple([MemberSchema, OrderDirSchema])),
]);
export type OrderSpec = z.infer<typeof OrderSpecSchema>;

export const CubeQuerySchema = z
  .object({
    measures: z.array(MemberSchema).optional(),
    dimensions: z.array(MemberSchema).optional(),
    timeDimensions: z.array(TimeDimensionSchema).optional(),
    filters: z.array(QueryFilterSchema).optional(),
    segments: z.array(MemberSchema).optional(),
    order: OrderSpecSchema.optional(),
    limit: orVar(z.number()).optional(),
    offset: orVar(z.number()).optional(),
    total: z.boolean().optional(),
    timezone: z.string().optional(),
  })
  .strict();
export type CubeQuery = z.infer<typeof CubeQuerySchema>;

/* ───────────────────────────── chart options ────────────────────────────── */

/**
 * The chart-family discriminator is an OPEN string, not a closed enum: a host can
 * add an entirely new family (via `<CubeVizProvider families={[...]}>`) and its specs
 * must validate. The builtin families ship in {@link BUILTIN_CHART_FAMILIES}; unknown
 * (host) families are dispatched through the injected family registry before any
 * builtin switch. `map` is no longer builtin — it moved to the host app.
 */
export const ChartFamilySchema = z.string().min(1);
export type ChartFamily = z.infer<typeof ChartFamilySchema>;

/** The families cube-viz ships in-box (the picker order). `map` and `combo` REMOVED
 *  (combo + dual-axis were dropped in schemaVersion 2; `heatmap` was added). */
export const BUILTIN_CHART_FAMILIES = [
  "bar",
  "line",
  "area",
  "pie",
  "scatter",
  "heatmap",
  "kpi",
  "table",
] as const;
export type BuiltinChartFamily = (typeof BUILTIN_CHART_FAMILIES)[number];

export const ChartColorTokenSchema = z.enum(["chart-1", "chart-2", "chart-3", "chart-4", "chart-5"]);
export type ChartColorToken = z.infer<typeof ChartColorTokenSchema>;

export const FormatKindSchema = z.enum([
  "number",
  "percent",
  "currency",
  "duration",
  "date",
  "auto",
]);
export type FormatKind = z.infer<typeof FormatKindSchema>;

export const FormatOptionsSchema = z
  .object({
    kind: FormatKindSchema.optional(),
    decimals: z.number().optional(),
    abbreviate: z.boolean().optional(),
    prefix: z.string().optional(),
    suffix: z.string().optional(),
    unitSystem: z.enum(["metric", "imperial"]).optional(),
    dateFormat: z.string().optional(),
    /** ISO 4217 currency code for `kind:"currency"` (e.g. "EUR"); defaults to USD. */
    currency: z.string().optional(),
  })
  .strict();
export type FormatOptions = z.infer<typeof FormatOptionsSchema>;

export const SeriesMetaSchema = z
  .object({
    label: z.string().optional(),
    colorToken: ChartColorTokenSchema.optional(),
    /** Series sharing an id stack together; DIFFERENT ids are separate stacks —
     *  side by side (bar) or overlaid (area). Only read when `stackMode` stacks. */
    stackId: z.string().optional(),
    // NOTE — there is deliberately no per-series `curve`. Line shape is a property of
    // the CHART (`familyOptions.curve`): a stacked/percent area draws a whole stack
    // from one mark, and a color-split chart has no per-measure meta at all, so a
    // per-series shape was ignored in exactly the cases users reached for it.
    // Removed in v5 (promoted to the family option by the migration).
    /** Per-series point markers (line/area) — overrides the family default. */
    dots: z.boolean().optional(),
    // NOTE — there is deliberately no per-series `format`. Numbers on ONE value axis
    // share a unit, so a per-series format would print two different units against the
    // same ticks; formatting is chart-level (`chart.format`) with per-axis /
    // per-column overrides. Removed in v3 (it parsed but nothing ever read it).
  })
  .strict();
export type SeriesMeta = z.infer<typeof SeriesMetaSchema>;

export const SeriesMappingSchema = z
  .object({
    category: z.object({ member: MemberSchema }).strict(),
    series: z.union([
      z
        .object({
          mode: z.literal("measures"),
          members: z.array(MemberSchema),
          meta: z.record(MemberSchema, SeriesMetaSchema).optional(),
        })
        .strict(),
      z
        .object({
          mode: z.literal("pivot"),
          /** The primary split measure — drives the value-axis unit. Always set
           *  (also the only value when a single measure is split by colour). */
          value: MemberSchema,
          /** When MORE THAN ONE measure is split by the colour dimension, the full
           *  ordered measure list (series = measure × pivot value). `value` is
           *  `values[0]`. Absent ⇒ single-measure pivot (the common case). */
          values: z.array(MemberSchema).optional(),
          pivot: MemberSchema,
          /** Per-MEASURE meta (keyed by measure): label/color/format overrides for
           *  each split measure's series. */
          meta: z.record(MemberSchema, SeriesMetaSchema).optional(),
        })
        .strict(),
    ]),
  })
  .strict();
export type SeriesMapping = z.infer<typeof SeriesMappingSchema>;

export const LegendOptionsSchema = z
  .object({
    show: z.boolean().optional(),
    /** Top or bottom only. A SIDE legend competes with the plot for width — the thing
     *  a dashboard tile has least of — so the renderer never had one and `left`/`right`
     *  silently became `bottom`. Removed from the enum in v3 (migrated to `bottom`). */
    position: z.enum(["top", "bottom"]).optional(),
  })
  .strict();
export type LegendOptions = z.infer<typeof LegendOptionsSchema>;

export const TooltipOptionsSchema = z
  .object({
    show: z.boolean().optional(),
    indicator: z.enum(["dot", "line", "dashed"]).optional(),
    showTotal: z.boolean().optional(),
  })
  .strict();
export type TooltipOptions = z.infer<typeof TooltipOptionsSchema>;

export const AxisOptionsSchema = z
  .object({
    /**
     * The axis title. UNSET ⇒ the mapped member's own name; EMPTY STRING ⇒ no title
     * (the ticks and line stay). There is no separate hide flag: the editor's title
     * field IS the control, and clearing it is how you remove the title. (v4)
     */
    label: z.string().optional(),
    /** Hide the whole axis — ticks, line and title. */
    hide: z.boolean().optional(),
    /** Value-axis only: a category axis is band/point/utc and has no log form. */
    scale: z.enum(["linear", "log"]).optional(),
    /** A FIXED value-axis window, both ends. There is no half-open form: the renderer
     *  either takes a configured domain verbatim or infers both ends from the data, so
     *  `[0, "auto"]` used to parse and then do nothing. Omit for auto. (v3) */
    domain: z.tuple([z.number(), z.number()]).optional(),
    /** FormatOptions for THIS axis' ticks, merged over the chart-level `format`. */
    tickFormat: FormatOptionsSchema.optional(),
  })
  .strict();
export type AxisOptions = z.infer<typeof AxisOptionsSchema>;

export const AxesOptionsSchema = z
  .object({
    x: AxisOptionsSchema.optional(),
    y: AxisOptionsSchema.optional(),
  })
  .strict();
export type AxesOptions = z.infer<typeof AxesOptionsSchema>;

export const ColorAssignmentSchema = z
  .object({
    byKey: z.record(z.string(), ChartColorTokenSchema).optional(),
    ramp: z.array(ChartColorTokenSchema).optional(),
  })
  .strict();
export type ColorAssignment = z.infer<typeof ColorAssignmentSchema>;

/** The default trailing window (in categories) for a `rollingAvg` transform. */
export const DEFAULT_TRANSFORM_WINDOW = 7;

export const TransformKindSchema = z.enum(["rollingAvg", "cumulative", "percentOfTotal"]);
export type TransformKind = z.infer<typeof TransformKindSchema>;

/**
 * A PRESENTATION transform applied to the already-aggregated, already-normalized
 * series — the seam TanStack Charts deliberately leaves to the view layer while the
 * semantic layer (Cube) owns aggregation. It lets "7-day rolling average" / "running
 * total" / "% of total" be a display choice instead of three new Cube measures.
 *
 * Envelope-level (NOT per-family) on purpose: it reshapes the generic
 * `{categories, series[].data}` shape, so every cartesian family gets it for free
 * and no family option schema grows a knob. Applied in `ChartRenderer` before the
 * family component sees the data (see `src/charts/transforms.ts`).
 */
export const ChartTransformSchema = z
  .object({
    kind: TransformKindSchema,
    /**
     * Trailing window length in CATEGORIES. Only meaningful for `kind:"rollingAvg"`
     * (ignored by cumulative / percentOfTotal); defaults to
     * {@link DEFAULT_TRANSFORM_WINDOW}.
     */
    window: z.number().int().min(2).max(90).optional(),
  })
  .strict();
export type ChartTransform = z.infer<typeof ChartTransformSchema>;

export const ChartOptionsSchema = z
  .object({
    family: ChartFamilySchema,
    /** Generic data→visual mapping. Used by bar/line/area/pie/heatmap; scatter/kpi/table
        carry their own mapping inside familyOptions, so this is optional at the envelope. */
    mapping: SeriesMappingSchema.optional(),
    orientation: z.enum(["vertical", "horizontal"]).optional(),
    stackMode: z.enum(["none", "stacked", "grouped", "percent"]).optional(),
    legend: LegendOptionsSchema.optional(),
    tooltip: TooltipOptionsSchema.optional(),
    axes: AxesOptionsSchema.optional(),
    colors: ColorAssignmentSchema.optional(),
    format: FormatOptionsSchema.optional(),
    /**
     * Presentation-only reshaping of the normalized series (rolling average /
     * running total / share of category total). Purely additive + optional, so it
     * did NOT bump {@link SCHEMA_VERSION} when it landed — every v2 spec stayed valid.
     */
    transform: ChartTransformSchema.optional(),
    /** Per-family escape hatch, validated by a family-specific schema after default-merge. */
    familyOptions: z.record(z.string(), z.unknown()).optional(),
  })
  .strict();
export type ChartOptions = z.infer<typeof ChartOptionsSchema>;

/* ─────────────────────────────── widgets ────────────────────────────────── */

/** ProseMirror / TipTap document JSON (`editor.getJSON()`). Loosely typed on purpose. */
export const TipTapDocSchema: z.ZodType<{ type: string; content?: unknown[] }> = z
  .object({ type: z.string(), content: z.array(z.unknown()).optional() })
  .passthrough();
export type TipTapDoc = z.infer<typeof TipTapDocSchema>;

export const InputControlKindSchema = z.enum([
  "dateRange",
  "granularity",
  "select",
  "memberSelect",
  "text",
  "number",
  "toggle",
]);
export type InputControlKind = z.infer<typeof InputControlKindSchema>;

export const InputControlSchema = z
  .object({
    variable: z.string().min(1),
    control: z.discriminatedUnion("kind", [
      z
        .object({
          kind: z.literal("dateRange"),
          presets: z.array(z.string()).optional(),
          allowFuture: z.boolean().optional(),
        })
        .strict(),
      z
        .object({
          kind: z.literal("granularity"),
          options: z.array(GranularitySchema).optional(),
          /** A dateRange variable whose span narrows the offered granularities. */
          rangeVariable: z.string().optional(),
        })
        .strict(),
      z
        .object({
          kind: z.literal("select"),
          options: z.array(z.object({ value: VariableValueSchema, label: z.string() }).strict()),
          multiple: z.boolean().optional(),
        })
        .strict(),
      z
        .object({
          kind: z.literal("memberSelect"),
          from: z.enum(["dimension", "measure", "dimensionOrMeasure"]),
          cube: z.string().optional(),
        })
        .strict(),
      z.object({ kind: z.literal("text"), placeholder: z.string().optional() }).strict(),
      z
        .object({
          kind: z.literal("number"),
          min: z.number().optional(),
          max: z.number().optional(),
          step: z.number().optional(),
        })
        .strict(),
      z.object({ kind: z.literal("toggle") }).strict(),
    ]),
  })
  .strict();
export type InputControl = z.infer<typeof InputControlSchema>;

const widgetBase = {
  id: z.string().min(1),
  title: z.string().optional(),
};

export const ChartWidgetSchema = z
  // `query` defaults to `{}` so QUERY-LESS families (e.g. a host `ai` summary tile that
  // renders from `familyOptions`, not a Cube query) validate without carrying a query.
  // `.default({})` (not `.optional()`) keeps parsed output query-bearing, so editor code
  // that spreads `spec.query`/`query.measures` never hits `undefined`. All CubeQuery
  // fields are themselves optional, so `{}` is a valid, empty query.
  .object({ ...widgetBase, type: z.literal("chart"), query: CubeQuerySchema.default({}), chart: ChartOptionsSchema })
  .strict();
export type ChartWidget = z.infer<typeof ChartWidgetSchema>;

export const TextWidgetSchema = z
  .object({ ...widgetBase, type: z.literal("text"), doc: TipTapDocSchema })
  .strict();
export type TextWidget = z.infer<typeof TextWidgetSchema>;

export const InputWidgetSchema = z
  .object({ ...widgetBase, type: z.literal("input"), control: InputControlSchema })
  .strict();
export type InputWidget = z.infer<typeof InputWidgetSchema>;

export const WidgetSpecSchema = z.discriminatedUnion("type", [
  ChartWidgetSchema,
  TextWidgetSchema,
  InputWidgetSchema,
]);
export type WidgetSpec = z.infer<typeof WidgetSpecSchema>;

/* ──────────────────────────── dashboard layout ──────────────────────────── */

export const LayoutItemSchema = z
  .object({
    i: z.string(),
    x: z.number(),
    y: z.number(),
    w: z.number(),
    h: z.number(),
    minW: z.number().optional(),
    minH: z.number().optional(),
    static: z.boolean().optional(),
  })
  .strict();
export type LayoutItem = z.infer<typeof LayoutItemSchema>;

export const GridConfigSchema = z
  .object({
    cols: z.number().optional(),
    rowHeight: z.number().optional(),
    margin: z.tuple([z.number(), z.number()]).optional(),
    containerPadding: z.tuple([z.number(), z.number()]).optional(),
  })
  .strict();
export type GridConfig = z.infer<typeof GridConfigSchema>;

export const VariableTypeSchema = z.enum([
  "dateRange",
  "time",
  "granularity",
  "string",
  "number",
  "boolean",
  "dimension",
  "measure",
  "dimensionOrMeasure",
]);
export type VariableType = z.infer<typeof VariableTypeSchema>;

export const VariableDeclSchema = z
  .object({
    name: z.string().min(1),
    type: VariableTypeSchema,
    label: z.string().optional(),
    array: z.boolean().optional(),
    default: VariableValueSchema.optional(),
  })
  .strict();
export type VariableDecl = z.infer<typeof VariableDeclSchema>;

/* ────────────────────────────── top-level specs ─────────────────────────── */

const specMeta = {
  schemaVersion: z.literal(SCHEMA_VERSION),
  id: z.string().min(1),
  name: z.string().optional(),
  description: z.string().optional(),
  createdAt: z.string().optional(),
  updatedAt: z.string().optional(),
};

export const ChartSpecSchema = z
  // Mirror ChartWidgetSchema: `query` defaults to `{}` so a query-less chart spec (an `ai`
  // family summary) validates without a query, while parsed output stays query-bearing.
  .object({ ...specMeta, kind: z.literal("chart"), query: CubeQuerySchema.default({}), chart: ChartOptionsSchema })
  .strict();
export type ChartSpec = z.infer<typeof ChartSpecSchema>;

export const DashboardSpecSchema = z
  .object({
    ...specMeta,
    kind: z.literal("dashboard"),
    variables: z.array(VariableDeclSchema),
    widgets: z.array(WidgetSpecSchema),
    layout: z.array(LayoutItemSchema),
    grid: GridConfigSchema.optional(),
  })
  .strict();
export type DashboardSpec = z.infer<typeof DashboardSpecSchema>;

export const SpecSchema = z.discriminatedUnion("kind", [ChartSpecSchema, DashboardSpecSchema]);
export type Spec = z.infer<typeof SpecSchema>;
